mapper.select:
SELECT * FROM professional_qualifications as pq join student_information as si on pq.student_number = si.student_number


        AND pq.student_name LIKE CONCAT('%',#{studentName},'%')


        AND pq.student_number LIKE CONCAT('%',#{studentNumber},'%')


        AND si.classes = #{classes}


        AND si.grade = #{grade}


        AND si.major = #{major}


        AND si.college = #{college}
